    summary: "徐达（1332—1385），字天德，濠州钟离（今安徽凤阳）人，明朝开国第一功臣、杰出军事家。他持重勇略，为朱元璋统兵四方：鄱阳湖败陈友谅，平江俘张士诚，旋拜征虏大将军，率二十五万大军北伐，攻克元大都，塞外追歼残元，中原遂定。明太祖亲制御赞，誉其「受命而出，成功而旋，不矜不伐」「大将军一人而已」。官至太傅、中书右丞相，封信国公、魏国公，病逝后追封中山王，谥武宁，配享太庙，肖像功臣庙位皆第一。终明一世，徐氏子孙世袭公爵，与国同休，为明初功臣中罕有之善终者。",
    background: "元朝至正年间，朝政溃乱，黄河泛滥。至正十一年（1351），刘福通于颍州起兵，红巾起义席卷全国；徐寿辉称帝蕲水，张士诚据高邮，方国珍乱海上，元廷顾此失彼。丞相脱脱罢死，帝党与太子党内争不休，扩廓帖木儿与孛罗帖木儿拥兵关中互攻，中原郡县陷入群雄逐鹿。江淮之间，陈友谅弑徐寿辉自立，据荆、汉上游，拥水师数十万；张士诚据两浙膏腴之地，兵精粮足。正当此时，徐达与朱元璋自微末起兵于濠，以应天为根基，转战江东。面对强大的陈友谅水师和张士诚精锐，徐达以持重沉稳、攻守相济的帅才逐一翦灭劲敌；随后主持明军历史上最大规模的北伐，彻底击溃蒙元大都中枢，结束了中原汉地长达数百年的战乱分裂，奠定大明开国疆域版图。一代将帅之崛起，实与元末天下崩解之大势相表里。",
