          "至正十五年（1355），徐达随朱元璋自和州渡江，破采石、下太平；次年攻克集庆路（今南京），朱元璋改集庆为应天府，以此为根基。此后徐达受命总兵东征，取镇江、常州，又断宜兴粮道克之。张士诚自高邮南下，屡遣精锐争常州，徐达以寡守御，伺隙出击，数挫其锋，应天东南屏障遂固。其时朱元璋西北当陈友谅、东当张士诚，徐达转战其间，屡立首功，渐次升迁至淮兴翼统军元帅、枢密院同佥，节制诸将。",
