    interpretation: "徐达之所以能居开国功臣之首而得善终，要在「持重」二字。用兵持重，故能先弱后强、稳扎稳打，鄱阳湖败陈友谅、平江困张士诚、北伐先山东后河南，皆此一理；自处持重，故能功高不矜、妇女无所爱、财宝无所取，于朱元璋猜忌日深之时独保令名。观乎明初，李善长以丞相之尊赐死，蓝玉以凉国公见族灭，而徐达病逝北平，善终牖下，配享太庙，子孙袭魏国公、定国公与国同休，足见「中正无疵」四字非虚誉。后世野史所谓朱元璋赐蒸鹅致死者，正史不载，史家多不采信，当为洪武朝大戮功臣之后民间的附会之辞。徐达经营的北平防御体系与边镇格局，后为燕王朱棣就藩所凭，亦为靖难之役与迁都北京埋下远因，其影响远逾于开国一役。",
