    interpretation: "李时珍的一生，恰处于明代由虚返实的思想转折之上。嘉靖、万历年间，王学末流空谈心性，方士以丹砂水银迎合帝王之好，医药界因循旧注、以讹传讹。李时珍却以脚踏实地的文献考据与实地观察，纠正了千余年来本草学问中的名物混淆与药性错记，把一味味草药的形态、产地、气味、主治都建立在可验证的事实之上。这种精神，与同时代徐光启、宋应星在农学、工艺领域的探索遥相呼应，共同构成晚明实学思潮的重要一翼。从世界史看，他与文艺复兴后的欧洲博物学家几乎同时，却以一己之力完成了一部集大成的博物志，使本草之学从方士的长生迷雾中回归治病救人的本义。达尔文誉之为「中国古代的百科全书」，并非过誉；其书为此后四百余年的药物学、博物学提供了取之不竭的矿藏，其方法则至今仍是中国科学史上实证传统的灯塔。",
