    interpretation: "蓝玉之死，常被视作功臣跋扈的自取之祸，但置于明初政治格局中，实为制度性清洗的必然一环。朱元璋以武力取天下，开国之初以功臣镇边、以铁券免死、以联姻固恩，是迫于形势的权宜。待天下既定，胡惟庸案废中书省、罢丞相，文官集团首当其冲；兵权虽归五军都督府与卫所，而蓝玉总领十五万大军、威震中外，恰是皇权不能容忍的第二个权势中心。若太子朱标在世，蓝玉尚可为柱石；朱标一薨，十五岁的朱允炆断然驾驭不了这位骄横的国公舅祖。朱元璋自比汉高祖，杀蓝玉正如汉高诛韩信、彭越，是为幼主除荆棘。蓝玉本人确有取死之道，然株连一万五千余人、功臣宿将诛戮殆尽，则远超一人之罪。其直接后果便是建文朝无将可用，靖难兵起，朱允炆终让位于叔父朱棣；皇权空前集中，而明初尚武之风亦随之凋零。功臣尽诛，换来的不是长治久安，而是藩王坐大。",
