    interpretation: "李成梁一身，兼为明代边镇体制之柱石与病变。辽东孤悬关外，卫所废坏，屯政不修，总兵唯有以私养家丁作战。成梁厚赏以固其心，赏赍无出，则仰给于朝廷特恩与冒功纳级，此杀良冒功之制度根源。张居正在，则特恩不绝；居正殁，清议起，劾罢随之。弃宽奠六堡，表面为老迈保守，实为边费不继、屯政大坏下之无奈收缩。其纵容努尔哈赤，本以夷制夷之常策，然建州雄长而明廷莫能制。故辽东之亡，非亡于万历四十六年之抚顺，实成于二百年卫所积弊与三十年镇将专兵之循环。养虎遗患之论，责其私心；空心化之说，得其大局。",
