          "四月二十四日，清军以红衣大炮轰击扬州西北城垣，城堞多坍。二十五日，城西北角陷，清兵蜂拥入城。史可法见大势已去，拔刀自刎，伤颈未殊，为清军所执。多铎亲至，以宾礼相待，劝其北面事清，且以洪承畴归降后受知遇为例。史可法正色答道：「城亡与亡，我意已决。即碎尸万段，甘之如饴。但扬州百万生灵，既属于尔，当好视之。」遂遇害，时弘光元年四月二十五日，年四十四岁。",
