    interpretation: "史可法之死，历来有两重读法。论才略，他并非挽狂澜于既倒的能臣：崇祯年间转战江淮，未能剿平流贼；弘光初年定策犹豫，先主潞王而后屈从马士英；督师江北，四镇骄悍不受节制，他调解无功，只能以苦心孤诣维系残局，史家或谓其将略非所长，此论不无道理。但南明之亡，根子在于朝局翻覆、藩镇割据与财用竭蹶，绝非一人可救。史可法真正不可及处，在于逢危难而志不夺、处必死而节不亏。扬州孤城无援，他本可如时辈一般献城乞降，却选择以一死酬国。正是这一死，使他从庸常的末世大员升格为民族气节的丰碑：清初百年之中，江南士庶私祭不辍；乾隆朝赐谥忠正，官方与民间的记忆合流。观其一生，师门教泽、家国崩解与个人生死，在扬州城头凝为一体——成败固难以逆料，气节却可以不朽。",
