    interpretation: "解缙之死，非死于才，实死于势。其以十九岁少年登第，受知太祖；靖难之后，又入直文渊阁，为内阁初创七臣之一，总裁《永乐大典》，位虽清要，品秩实卑，而预机密、议大政，尤以「好圣孙」一语，定永乐一朝之国本，此其功也，亦其祸也。汉王朱高煦以爱子而觊储位，武将勋贵附之，党势盘根错节；解缙一介词臣，无尺寸之柄，而以口舌立定大计，名高见忌，谤书日至，一贬再谪，终至瘐死雪中，妻子流徙，此非一己之祸，乃皇权之下，文臣预政而无所凭依者之共同命运。观其一生，太祖赏其才而斥其轻，成祖用其学而弃其身，纪纲一武夫，奉「缙犹在耶」一语即取其命，可见天子一念之间，荣辱生死系焉。然《永乐大典》二万二千余卷，网罗天下遗书，解缙总其成，使三代以下文献不坠，其功自能与典籍同传，不待谥号而自彰。",
