    interpretation: "徐光启一生，可作三层读解。其一，他是以程朱举业出身而系统接受西方科学的第一代中国士大夫。在「夷夏之辨」笼罩的晚明，他主张「苟利于国，远近何论焉」，把西学定位为补益国运的实学而非异端，这种胸襟在有明一代士人中堪称罕见。其二，他示范了一种新的方法论：《几何原本》的公理推演、《崇祯历书》的实测校验、《农政全书》的田间试验，三者贯穿着同一种精神——凡事求证据、求精微、求可操作，以「会通」为「超胜」的前提，既不泥古，也不盲外。其三，他的命运是晚明士大夫的悲剧缩影：练兵之策困于无饷，历书未竟而国祚已倾。清军入关后，汤若望以《崇祯历书》为基础进呈《时宪历》，使他的历算成果服务于新朝；而他手定的几何术语与农学遗产，则长久地融入了中国人的日常生活。",
