          "退居之暇，徐阶手辑著述，有《世经堂集》《少湖文集》传于世，又与门生故旧讲论经史，谦抑如老诸生。然其家奴子弟积习难改，纵释不悛，弹章屡及，徐阶虽约束之，终不能尽革，遂为晚年之大累。海瑞巡抚应天仅数月，即因劾奏权贵、忤逆当道而罢官去，徐氏之田产家奴，亦稍稍复故态，江南积弊，终非一人之力所能尽挽也。",
