    interpretation: "徐阶之历史地位，须置于明代皇权政治之结构中理解。其一，内阁本为票拟之职，无宰相之名而有相权之实，首辅之进退，系于皇帝一人之眷顾。徐阶以青词起家，以遗诏立功，其权皆源于皇权之委托；倾覆严嵩，非制度之更张，乃恩宠之转移，此明代内阁政治之根本局限。其二，徐阶独草遗诏，以先帝口吻罢斋醮、平冤狱，实为明代政治史上罕见之变局——以臣子之笔，行君父之悔，既免新君即位之纷争，又收拨乱反正之效，张居正后来之改革，即沿此格局而行。其三，徐阶晚年田产家奴之祸，暴露江南士绅兼并土地、优免赋役之积弊，虽海瑞以刚直绳之，终不能久。故徐阶之毁誉参半，非独个人之失，实时代制度之缩影。",
