    interpretation: "徐渭的一生，是晚明天才与时代冲突的缩影。八股取士重格式而轻真才，使他八赴乡试不第，功名无门，只能以幕僚之身曲折施展抱负；而幕府人才依附于权臣，严嵩、胡宗宪败亡，幕客随之星散，士人的命运完全系于人主之兴衰，这正是明代政治结构的一大痼疾。他的悲剧不在于才不足，而在于才与世忤。师从王阳明弟子季本、王畿，深受心学狂狷一脉熏陶，使他不肯俯就八股与礼法；其自戕与杀妻，既是狂疾所致，也是时代压逼下的极端爆发。而正是这股「不平则鸣」的郁勃之气，造就了他在艺术上的开宗立派：大写意花鸟的泼墨淋漓、《四声猿》的悲歌慷慨、诗歌的独抒性灵，皆是同一生命能量的宣泄。徐渭生前寂寥，身后却被公安派与石涛、八大山人、郑板桥、吴昌硕、齐白石一代代追慕，实因其艺术让文人画彻底脱离工整写实的旧轨，把个体的精神痛苦化为笔墨的本体。他与李贽同属晚明个性解放思潮的先驱，一在思想，一在笔墨，同声相应，同气相求。",
