    interpretation: "严嵩专政近二十年，表面是权臣擅权，根子却在皇权体制本身。世宗以藩王入统，借大礼议击碎旧臣格局，又移居西苑斋醮，把日常理政之权委于内阁，而以帝眷为唯一取舍——首辅之位不再系于才德功业，而系于能否迎合皇帝的私欲与猜忌。严嵩的青词、倾陷与隐忍，都是这套机制的产物。另一方面，严氏父子把持用人、卖官鬻爵，使嘉靖中期吏治腐败深入肌理，边备废弛，北患与倭患交乘，沈炼、杨继盛之死更暴露言路与司法的败坏。徐阶倒严，仍沿用同一逻辑——借道士扶乩、密疏构陷而成事，并未触动制度。故严嵩虽诛、《明史》虽列之《奸臣传》，而阁臣依附皇权、权相专政的痼疾未除，万历初张居正之兴废，仍可看到同一逻辑的重演。",
