    interpretation: "杨涟之死，非一士之生死，而是晚明政治结构总崩解的缩影。明代废丞相、升六部，皇权独揽，内廷司礼监代行批红，外朝内阁仅有票拟；遇庸主在位，政柄便落入近侍宦官之手。魏忠贤以司礼监秉笔太监兼掌东厂，复结锦衣卫诏狱，矫旨黜陟，廷杖大臣，实将皇权的制度性暴力集于一身。杨涟以二十四大罪劾之，所据者唯祖制、伦理与清议，而熹宗一旨切责，便使直臣束手——道德与舆论在此结构中全无强制力。东林党争至此已非政见之争，而是正邪存亡之搏。崇祯即位，诛忠贤、定逆案、赠谥杨涟，既为昭雪，亦是新君借平反东林重建统治正当性。由此，杨涟与东林六君子从受难者化为政治符号：其直声与死节，成为清初士人反思明亡、标举气节的核心资源；而明代宦官专权与士大夫殉道的循环，亦随明亡而告终。",
