          "嘉靖八年（1529）六月，杨廷和卒于新都，年七十一。讣闻京师，世宗问大学士李时曰：「廷和何如人？」对曰：「臣不足以及廷和。」世宗默然良久。以削籍故，卒无恤典，恩礼缺然。朝野闻之，皆为叹息，士大夫私吊者相望于道。其子杨慎时谪戍云南，闻丧奔归，哀毁骨立，庐于墓侧。",
          "隆庆元年（1567），穆宗即位，复杨廷和官，赠太保，谥文忠，荫一子入国子监读书，恤典始备。《明史》论曰：「杨廷和、梁储、蒋冕、毛纪、石珤等，皆端谨自守，不为危言激论，而侃侃正色，屹然大臣之概。」廷和历仕四朝，定策安国，再安宗社，虽中道蹉跌，削籍以殁，卒赖后人昭雪，复其显名，可谓青史昭然矣。"
