    interpretation: "杨廷和一生，以正德十六年定策与嘉靖三年罢归为两大关捩。定策之际，武宗无嗣，江彬拥兵，廷和以《皇明祖训》「兄终弟及」为据，奉慈寿皇太后懿旨迎立世宗，总揽朝政三十七日，计擒江彬，尽革弊政，不动声色而定危局，此非素负重望、临事不惧者不能。然大礼之议起，廷和持汉定陶、宋濮王故事，坚主世宗当以孝宗为皇考，论据虽正，而于世宗本生父子之情，终少委曲。议礼之争，前后三年，群臣伏阙受杖，朝局大伤；张璁、桂萼以议礼骤贵，门户之渐开，明代政局为之一变。廷和之去，非仅一人之进退，实皇权与相权消长之一大关键：内阁之权，经此挫抑，渐为帝意所驾驭。隆庆初复官，赠太保，谥文忠，则天下公论所在，终不可泯。",
