    interpretation: "俞大猷的一生，是明代军事制度困局的缩影。卫所世袭制本应世出将才，实则武职沉沦下僚，升迁之路阻塞；俞大猷须借武会试、督抚举荐与战功，才能从百户升至总兵。而「以文制武」的格局下，武将动辄遭劾：王江泾大捷之功未酬，岑港久攻即遭革职，汪直案中更下诏狱、夺世荫，几丧性命。功与罚之间巨大的落差，说明嘉靖朝的军事失败首先不是前线的问题，而是朝廷的问题。俞大猷的可贵，在于身处逆境仍以兵学自任。他以《易》理论兵，著《剑经》专述棍法，开「以书论武」之新风，戚继光《纪效新书》亦采其法；北戍大同献独轮车阵法，以车阵载佛郎机、鸟铳，车步骑协同破骑兵，为明代火器战术作了开创性探索。他与戚继光并称「俞龙戚虎」，戚继光得胡宗宪、张居正倚重，俞大猷则不肯依附权贵，数起数落而志不少衰。万历八年（1580）他默默卒于家，赠左都督，谥武襄，身后留下的不只是战功，更是一个儒将的精神范本。",
