    interpretation: "左光斗一生，由移宫定策到诏狱殉难，折射出明末政治的三重困境。其一，皇权依附内廷。移宫案中，科道官员以祖制与舆论逼退李选侍，所恃者仅是天启帝初即位时的权力真空；一旦皇权与乳母、近珰结合，科道即束手无策。其二，监察制度失灵。左光斗身为左佥都御史，纠劾之权止于外朝，而魏忠贤身兼司礼监秉笔、提督东厂，属皇帝私属，弹劾权珰实等挑战皇权。三十二斩罪之疏辞切理尽，而奏疏留中、削籍逮狱，说明制度内表达渠道已尽堵死。其三，诏狱越法。阉党以坐赃之名行迫害之实，镇抚司不经三法司，五日一比，酷刑毙命，所毁者不止六人之命，更是士大夫与朝廷的信任。崇祯初虽平反追谥，而党争创伤已深，国势终不可挽。门生史可法扬州殉难，为其精神余脉。",
