          "承畴被俘后，解送盛京沈阳，初誓死不降，绝食数日，求死不得。清廷素重其才，太宗皇太极先后遣汉臣范文程、张存仁等前往说之。据《清史稿》所载，范文程往见时，承畴屡拂衣袖之尘，范氏由此判断其未怀死志——盖视死如归之人，无暇顾及衣冠尘垢也。承畴亦心知明朝大势已去：关外精锐尽没，关内流寇方炽，崇祯朝政紊乱，已无回天之力，此其内心动摇之由。",
          "随后皇太极亲至羁所，解所御貂裘披于承畴之身，殷勤慰问。承畴瞠目久视，叹曰「真命世之主也」，乃叩头请降。此即流传甚广之「解裘衣之」故事，为正史所载；而后世民间盛传庄妃（即后来的孝庄太后）亲奉参汤劝降之说，则出自野史笔记与戏曲演义，不见于《明史》《清史稿》等官修史书，并无史实依据，仅可视为后人附会之谈，不足凭信。",
          "松山之败的噩耗传至京师，崇祯帝初以为承畴已殉国，痛惜不已，特设坛于都城，亲临哭奠，辍朝示恤，朝臣多有赋诗悼之者。未几，承畴降清之讯传至北京，崇祯帝震怒，祭奠之举中辍，朝野上下哗然，士林尤为痛心。承畴在家乡南安之亲族亦深受其累，闽中士子引以为辱。此一降之间，承畴由国之干城一变而为千夫所指，其一生功名节操，自此判为两截。"
