    interpretation: "洪承畴一生，前半段是明末最成功的剿寇统帅，后半段是清初最能干的汉臣经略。对明朝，他平陕西、守辽东，可谓尽瘁；对清朝，他定江南、平云贵，可谓尽功。但两个政权互为仇雠，一身事二主，在传统忠节观下便无法两全。乾隆四十一年（1776），清高宗弘历下令编纂《贰臣传》，将降清的明朝臣工单列一编，上谕称其「皆系胜国臣工，遭际时艰，不能为其主临危受命」——承畴以功业之最，列于甲编之首。这一处置，既是对其背明事清的政治定性，也是清代稳定自身忠节秩序的需要：褒扬明末殉国诸臣、贬抑降附之臣，正是新王朝巩固正统的策略。承畴的功与罪，由此被置于不同时代的评价体系之中，至今仍难一语定论。",
