    interpretation: "利玛窦的传教策略，核心在于「适应」二字：先学语言，再习儒籍，由僧服而易儒服，以「西儒」自居；论学则以天主合于敬天，以算学舆地辅翼儒术。这一策略的本质，是承认中国文化的主体地位，再于其中寻找契合点，故能入肇庆、进南昌、留南京、立足京师。万历帝赐第与赐葬，象征朝廷对这一策略事实上的承认。然而适应政策有其内在张力：士大夫所重者是其历算舆图，非其天主之教；沈㴶兴南京教案，所攻者正是教义与礼仪。科学史上的地位，则以《几何原本》前六卷与《坤舆万国全图》为最。点线面体诸译名，至今沿用；五大洲观念，改变了中国人的世界图景。他与徐光启、李之藻等人的合作，开创了中西学术对译的体例：西人授意、华人笔录、反复润色。这一模式被清代历局、译馆继承。可以说，明清之际西学之所以能扎根，不在炮舰，而在利玛窦所代表的对话姿态。其成败得失，皆系于此。",
