    summary: "秦良玉（1574—1648），字贞素，四川忠州人，嫁石砫宣抚使马千乘为妻，夫死于狱后代领土司兵职。所部白杆兵持白木长矛、矛端带钩，善山地作战，号令严明，所过秋毫无犯。万历二十七年（1599）从征播州杨应龙，破金筑寨、取桑木关，为南川路战功第一；天启元年（1621）浑河之战后请缨率三千兵入卫，赐二品服；崇祯三年（1630）勤王收复永平、遵化等四城，平台召见，崇祯帝赐诗四章；隆武二年（1646）南明晋封忠贞侯。她是中国正史中唯一以战功单独立传于将相列传的女将军。",
    background: "明代在西南推行土司制度，凡西南夷朝贡者，皆以原地首领土官世袭，授宣慰使、宣抚使、安抚使等职，颁印信、定承袭，战时听朝廷征调，不改其俗、不夺其地。石砫宣抚司隶属四川重庆卫，地处川东万山之中，接荆襄、控巴黔，民风劲悍，兵农合一。万历中叶，天下承平已久，卫所兵制崩坏，京营与边兵多不堪战，一旦有急，朝廷辄调西南土司狼兵、白杆兵赴援。播州宣慰使杨应龙之乱即在此背景下爆发，万历二十七年（1599）明廷起李化龙为总督，调八路大军二十四万进剿，石砫兵隶南川路，秦良玉、马千乘夫妇由此登上战阵。良玉出身忠州书香武略之家，父秦葵通兵略，课子侄习武，良玉自幼兼通词翰、娴于骑射，嫁马千乘后佐理军务。明末辽东、西南、中原三线作战，兵制败坏，正给土司兵与女将提供了非常规的崛起之机。",
