        heading: "平台赐诗四城奏捷",
        paragraphs: [
          "崇祯二年（1629）十月，后金皇太极率兵入关，下遵化等城，直逼京师，是为己巳之变。三年春，良玉闻警，散家资、捐橐中金，率白杆兵勤王。时诸镇兵多观望不前，良玉独星驰赴难。与辽东总兵祖大寿等部协力，先复遵化，旋下永平、迁安、滦州四城，后金兵退出关外。京师解严，朝野震动。庄烈帝（崇祯帝）优诏褒美，召良玉于平台，慰劳再三，赐彩币羊酒，并御制诗四章以褒其忠勇，恩礼之隆，近世未有。",
          "赐诗有云：「学就西川八阵图，鸳鸯袖里握兵符。由来巾帼甘心受，何必将军是丈夫。」以帝王之尊，赋诗褒一女将，有明二百七十余年，秦良玉一人而已（按赐诗全章流传本异文颇多，正史所载仅此数句）。平台召见后，良玉上疏，请蠲石砫历年逋赋，抚恤阵亡将士家口，皆报可。其于白杆兵阵亡者之家，岁给米帛，终身不废，故部曲怀恩，效死如归，白杆兵虽屡经大创，犹能聚之成军。",
          "崇祯末，中原大乱，张献忠、罗汝才复炽。崇祯十六年（1643）后，张献忠由楚入川，连陷夔州、重庆，所至屠戮。良玉已老病，然犹提兵守川东，分遣部将守忠州、万县、夔州诸要害，而自率精锐坐镇石砫，誓与宗社共存亡。献忠遣使赍金帛招降，良玉斩其使，誓众拒之。献忠悉众攻之，不克；惮白杆兵锋锐，终不敢犯石砫。其后献忠屠川，州县残破，惟石砫一境独全，流民归之如市，全活者数十万人。"
        ]
