    interpretation: "秦良玉之崛起，根植于明代土司制度：朝廷赐土司世袭官职、颁印信，平时自治其民，战时听调从征。石砫地处川东山区，白杆兵的长矛钩镰、结阵连环，正是山地步兵克制骑兵的战法，与戚家军鸳鸯阵有异曲同工之妙。浑河一战，白杆兵与戚家军同日覆没，却令后金付出沉重代价，可见其战力。明末三大危机——后金、西南土司叛乱、农民军——石砫一军皆预其事，这恰是明王朝卫所兵制崩坏、军事动员捉襟见肘的写照。崇祯平台赐诗、隆武封忠贞侯，皆以朝廷名器褒一女将，既是酬功，也是南明政权借良玉的忠贞符号维系正统。石砫独全，则揭示乱世中的生存逻辑：地形险要、部曲善战、号令严明三者缺一不可。",
