    interpretation: "孙承宗的历史地位，系于三端。其一为战略：明代御边，自嘉靖后动言祖宗成宪，九边皆恃长城。承宗督师，主「守而后战」，以宁远、锦州、大凌河为节节推进之据点，以城制骑，以屯养兵，以辽人守辽土，关宁锦防线遂为明末二十余年国策所系。宁远、宁锦、松锦诸役，皆在此防线内展开；清军终不得正面破关，乃有崇祯二年绕道蒙古入塞之举，反证此防线之效。其二为制度：以兵部尚书兼东阁大学士督师，开阁臣典兵之例，意在以中枢重臣统驭文武。然承宗四起四落，柳河小败即遭诬劾，大凌河一挫即引疾归，可见党争之下，边帅进退不取决于军功而取决于朝局，实为明亡之一大机括。其三为气节：高阳阖门殉难，十九人同死，承宗望阙投缳，为有明士大夫殉国典型，宜乎南明追赠太师、谥文忠也。",
